<?php
$report = is_array($contentPriorities ?? null) ? $contentPriorities : [];
$portfolio = is_array($report['portfolio'] ?? null) ? $report['portfolio'] : [];
$integrity = is_array($report['integrity'] ?? null) ? $report['integrity'] : [];
$integrityPortfolio = is_array($integrity['portfolio'] ?? null) ? $integrity['portfolio'] : [];
$depth = is_array($report['content_depth'] ?? null) ? $report['content_depth'] : [];
$exposure = is_array($report['exposure'] ?? null) ? $report['exposure'] : [];
$weakness = is_array($report['weakness'] ?? null) ? $report['weakness'] : [];
$study = is_array($report['study_depth'] ?? null) ? $report['study_depth'] : [];
$priorityRows = is_array($report['priorities'] ?? null) ? $report['priorities'] : [];
$semanticAuditRows = is_array($report['semantic_audit']['management_services'] ?? null) ? $report['semantic_audit']['management_services'] : [];
$englishAuditRows = array_values(array_filter(
    is_array($report['semantic_audit']['questions'] ?? null) ? $report['semantic_audit']['questions'] : [],
    static fn(array $row): bool => ($row['board_id'] ?? '') === 'let' && ($row['subject_id'] ?? '') === 'english'
));
$regulatoryAuditRows = array_values(array_filter(
    is_array($report['semantic_audit']['questions'] ?? null) ? $report['semantic_audit']['questions'] : [],
    static fn(array $row): bool => ($row['subject_id'] ?? '') === 'cpa-regulatory-framework'
));
$boardRows = is_array($report['boards'] ?? null) ? $report['boards'] : [];
$integrityBoards = [];
foreach (($integrity['boards'] ?? []) as $boardKey => $board) {
    if (is_array($board)) {
        $boardId = (string) ($board['board_id'] ?? $boardKey);
        if ($boardId !== '') {
            $integrityBoards[$boardId] = $board;
        }
    }
}
$escape = static fn(mixed $value): string => htmlspecialchars((string) $value, ENT_QUOTES, 'UTF-8');
$displayAuditState = static fn(mixed $value): string => strtoupper((string) $value) === 'UNKNOWN' ? 'UNASSESSED' : (string) $value;
$status = (string) ($portfolio['integrity_status'] ?? 'UNKNOWN');
$statusClass = $status === 'FAIL' ? 'badge-danger' : ($status === 'PASS' ? 'badge-success' : 'badge-warning');
$metric = static fn(array $row, string $key, mixed $fallback = 0): mixed => $row[$key] ?? $fallback;
?>
<section class="page-header"><div><p class="eyebrow">Developer planning report</p><h1>Content Intelligence</h1><p>Use measured coverage, usage, learner outcomes, and study depth to choose the next content investment.</p></div><div class="page-actions"><a class="button secondary" href="/developer">Developer dashboard</a><a class="button" href="/question-import">Import questions</a></div></section>

<section aria-labelledby="intelligence-summary-heading"><div class="section-heading"><div><h2 id="intelligence-summary-heading">Portfolio Summary</h2><p class="muted">Structural integrity remains the release gate; investment signals are descriptive and sample-qualified.</p></div><span class="badge <?= $escape($statusClass) ?>"><?= $escape($status) ?></span></div><div class="ui-metric-grid"><article class="card stat-card"><span class="stat-label">Boards</span><strong class="stat-value"><?= (int)($integrityPortfolio['total_boards'] ?? count($boardRows)) ?></strong></article><article class="card stat-card"><span class="stat-label">Canonical questions</span><strong class="stat-value"><?= (int)($integrityPortfolio['total_canonical'] ?? $portfolio['question_count'] ?? 0) ?></strong></article><article class="card stat-card"><span class="stat-label">Eligible / linked</span><strong class="stat-value"><?= (int)($integrityPortfolio['total_eligible'] ?? 0) ?> / <?= (int)($integrityPortfolio['total_linked'] ?? 0) ?></strong></article><article class="card stat-card"><span class="stat-label">Flashcards</span><strong class="stat-value"><?= (int)($integrityPortfolio['total_derivable_cards'] ?? 0) ?></strong><span class="muted">+ <?= (int)($integrityPortfolio['total_justified_exclusions'] ?? 0) ?> justified exclusions</span></article><article class="card stat-card"><span class="stat-label">Questions with usage</span><strong class="stat-value"><?= (int)($portfolio['learner_usage']['questions_with_usage'] ?? 0) ?></strong><span class="muted">of <?= (int)($portfolio['question_count'] ?? 0) ?></span></article><article class="card stat-card"><span class="stat-label">Never seen</span><strong class="stat-value"><?= (int)($portfolio['learner_usage']['questions_never_seen'] ?? 0) ?></strong><span class="muted">not a defect by itself</span></article><article class="card stat-card"><span class="stat-label">High exposure</span><strong class="stat-value"><?= count($exposure['high_exposure'] ?? []) ?></strong></article><article class="card stat-card"><span class="stat-label">High-confidence weak areas</span><strong class="stat-value"><?= count($weakness['high_confidence_weak_areas'] ?? []) ?></strong><span class="muted">sample-qualified</span></article><article class="card stat-card"><span class="stat-label">Shallow areas</span><strong class="stat-value"><?= count($depth['shallow_subjects'] ?? []) + count($depth['shallow_topics'] ?? []) + count($depth['shallow_concepts'] ?? []) ?></strong><span class="muted">subject/topic/concept</span></article></div></section>

<section aria-labelledby="priority-heading"><div class="section-heading"><div><p class="eyebrow">Ranked next actions</p><h2 id="priority-heading">Content Priorities</h2></div><span class="badge badge-info"><?= count($priorityRows) ?> shown</span></div><?php if ($priorityRows === []): ?><div class="empty-state">No actionable priority candidates were detected.</div><?php else: ?><div class="table-wrap"><table><caption class="sr-only">Ranked content investment priorities</caption><thead><tr><th>Rank</th><th>Target</th><th>Score</th><th>Reason codes</th><th>Supporting metrics</th><th>Recommended action</th></tr></thead><tbody><?php foreach ($priorityRows as $row): ?><tr><td><?= (int)($row['rank'] ?? 0) ?></td><th scope="row"><code><?= $escape($row['target'] ?? '') ?></code><br><span class="muted"><?= $escape(strtoupper((string)($row['level'] ?? ''))) ?></span><?php $rowMetrics = is_array($row['supporting_metrics'] ?? null) ? $row['supporting_metrics'] : []; ?><?php if (isset($rowMetrics['content_fit_state']) || isset($rowMetrics['source_support_state'])): ?><br><small class="muted">Fit: <?= $escape($rowMetrics['content_fit_state'] ?? 'UNKNOWN') ?> · Sources: <?= $escape($rowMetrics['source_support_state'] ?? 'UNKNOWN') ?></small><?php endif; ?></th><td><strong><?= $escape($row['priority'] ?? '') ?></strong></td><td><?= $escape(implode(', ', array_map('strval', (array)($row['reason_codes'] ?? []))) ?: 'NONE') ?></td><td><?php $metrics = $rowMetrics; ?><ul><?php foreach ($metrics as $key=>$value): ?><?php if (is_scalar($value) || $value === null): ?><li><?= $escape($key) ?>: <?= $escape($value ?? 'n/a') ?></li><?php endif; ?><?php endforeach; ?></ul></td><td><strong><?= $escape($row['recommended_action'] ?? 'NO_ACTION') ?></strong><details><summary>IDs / explanation</summary><p><?= $escape(implode('; ', array_map('strval', (array)($row['explanation'] ?? [])))) ?></p><code><?= $escape(implode(', ', array_map('strval', (array)($row['affected_ids'] ?? [])))) ?></code></details></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?><p class="muted">Scores are transparent planning heuristics. Blueprint targets are repository configuration and are not presented as official beyond their stored metadata.</p></section>

<section aria-labelledby="board-depth-heading"><div class="section-heading"><h2 id="board-depth-heading">Board Readiness / Depth</h2><span class="badge badge-info">All registered boards</span></div><div class="table-wrap"><table><caption class="sr-only">Board depth and readiness matrix</caption><thead><tr><th>Board</th><th>Questions</th><th>Eligible</th><th>Linked</th><th>Cards</th><th>Resources</th><th>Usage</th><th>Status</th></tr></thead><tbody><?php foreach ($boardRows as $boardId=>$row): ?><?php $integrityBoard = $integrityBoards[(string)$boardId] ?? []; $boardStatus = (string)($integrityBoard['readiness_status'] ?? 'UNKNOWN'); $subjects = array_values(array_filter($depth['subjects'] ?? [], static fn(array $subject): bool => ($subject['board_id'] ?? '') === (string)$boardId)); $topics = array_values(array_filter($depth['topics'] ?? [], static fn(array $topic): bool => ($topic['board_id'] ?? '') === (string)$boardId)); ?><tr><th scope="row"><?= $escape($integrityBoard['board_name'] ?? $row['name'] ?? $boardId) ?><br><code><?= $escape($boardId) ?></code></th><td><?= (int)($row['question_count'] ?? 0) ?></td><td><?= (int)($row['eligible_question_count'] ?? 0) ?></td><td><?= (int)($row['linked_question_count'] ?? 0) ?></td><td><?= (int)($row['flashcard_count'] ?? 0) ?><?php if ((int)($row['flashcard_exclusion_count'] ?? 0) > 0): ?> <span class="muted">(+<?= (int)$row['flashcard_exclusion_count'] ?> excluded)</span><?php endif; ?></td><td><?= (int)($row['study_resource_count'] ?? 0) ?></td><td><?= $escape($row['usage']['accuracy'] ?? 'INSUFFICIENT_DATA') ?></td><td><span class="badge <?= $escape($boardStatus === 'FAIL' ? 'badge-danger' : ($boardStatus === 'PASS' ? 'badge-success' : 'badge-warning')) ?>"><?= $escape($boardStatus) ?></span><details><summary>Drilldown</summary><p>Subjects: <?= count($subjects) ?>; topics: <?= count($topics) ?>.</p><ul><?php foreach ($subjects as $subject): ?><li><?= $escape($subject['name']) ?>: <?= (int)$subject['question_count'] ?> questions, <?= (int)$subject['study_resource_count'] ?> resources</li><?php endforeach; ?></ul><p>Shallow topics: <?php $shallowBoardTopics = array_values(array_filter($depth['shallow_topics'] ?? [], static fn(array $item): bool => ($item['board_id'] ?? '') === (string)$boardId)); ?><?= $escape(implode(', ', array_column($shallowBoardTopics, 'target')) ?: 'none') ?></p><p>Priority candidates: <?php $boardPriorities = array_values(array_filter($priorityRows, static fn(array $item): bool => ($item['board_id'] ?? '') === (string)$boardId)); ?><?= $escape(implode(', ', array_column($boardPriorities, 'target')) ?: 'none') ?></p><?php if (!empty($integrityBoard['defects'])): ?><ul><?php foreach ($integrityBoard['defects'] as $defect=>$ids): ?><?php if ($ids !== []): ?><li><?= $escape($defect) ?>: <?= $escape(implode(', ', array_map('strval', (array)$ids))) ?></li><?php endif; ?><?php endforeach; ?></ul><?php endif; ?></details></td></tr><?php endforeach; ?></tbody></table></div></section>

<section aria-labelledby="usage-heading"><div class="section-heading"><h2 id="usage-heading">Usage / Exposure</h2><span class="badge badge-info">Descriptive</span></div><div class="ui-metric-grid"><article class="card stat-card"><span class="stat-label">Never seen</span><strong class="stat-value"><?= count($exposure['never_seen'] ?? []) ?></strong></article><article class="card stat-card"><span class="stat-label">Low exposure</span><strong class="stat-value"><?= count($exposure['low_exposure'] ?? []) ?></strong></article><article class="card stat-card"><span class="stat-label">Normal exposure</span><strong class="stat-value"><?= count($exposure['normal_exposure'] ?? []) ?></strong></article><article class="card stat-card"><span class="stat-label">High exposure</span><strong class="stat-value"><?= count($exposure['high_exposure'] ?? []) ?></strong></article></div><details><summary>Question-level exposure drilldown</summary><div class="table-wrap"><table><thead><tr><th>Question</th><th>Board / topic</th><th>Used</th><th>Correct</th><th>Incorrect</th><th>Accuracy</th><th>Class</th></tr></thead><tbody><?php foreach (array_slice(array_values($exposure['questions'] ?? []), 0, 25) as $item): ?><tr><th scope="row"><code><?= $escape($item['question_id']) ?></code></th><td><?= $escape(($item['board_id'] ?? '') . ' / ' . ($item['topic_id'] ?? '')) ?></td><td><?= (int)$item['times_used'] ?></td><td><?= (int)$item['times_correct'] ?></td><td><?= (int)$item['times_incorrect'] ?></td><td><?= $escape($item['accuracy'] ?? 'n/a') ?></td><td><?= $escape($item['exposure_class'] ?? '') ?></td></tr><?php endforeach; ?></tbody></table></div><p class="muted">Showing up to 25 records; complete ID lists remain in CLI JSON.</p></details></section>

<section aria-labelledby="weakness-heading"><div class="section-heading"><h2 id="weakness-heading">Learner Weakness</h2><span class="badge badge-info">Minimum sample <?= (int)($weakness['minimum_sample_size'] ?? 5) ?></span></div><?php if (empty($weakness['high_confidence_weak_areas'])): ?><div class="empty-state">No sample-qualified weak areas were detected.</div><?php else: ?><div class="table-wrap"><table><caption class="sr-only">Sample-qualified learner weakness areas</caption><thead><tr><th>Area</th><th>Sample size</th><th>Accuracy</th><th>State</th><th>Question IDs</th></tr></thead><tbody><?php foreach ($weakness['high_confidence_weak_areas'] as $area): ?><tr><th scope="row"><code><?= $escape($area['target']) ?></code></th><td><?= (int)$area['sample_size'] ?></td><td><?= $escape($area['accuracy']) ?>%</td><td><?= $escape($area['sample_state']) ?></td><td><code><?= $escape(implode(', ', array_map('strval', (array)($area['question_ids'] ?? [])))) ?></code></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?><details><summary>Insufficient-data areas</summary><p class="muted">These areas are reported for transparency, not as recommendations.</p><code><?= $escape(implode(', ', array_map(static fn(array $item): string => (string)($item['target'] ?? ''), array_slice($weakness['insufficient_sample_areas'] ?? [], 0, 50)))) ?></code></details></section>

